    "/api/questions": {
      "post": {
        "tags": [
          "MCQ"
        ],
        "summary": "Create new MCQ question",
        "description": "Access: Trainer/Admin",
        "security": [
          {
            "bearerAuth": []
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "prompt",
                  "options",
                  "correctOptionIndex"
                ],
                "properties": {
                  "prompt": {
                    "type": "string",
                    "example": "Which protocol is used for stateless communication in REST?"
                  },
                  "options": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    },
                    "example": [
                      "HTTP/HTTPS",
                      "SSH",
                      "FTP",
                      "Telnet"
                    ]
                  },
                  "correctOptionIndex": {
                    "type": "integer",
                    "example": 0
                  },
                  "explanation": {
                    "type": "string",
                    "example": "REST APIs communicate over HTTP/HTTPS."
                  },
                  "difficulty": {
                    "type": "string",
                    "enum": [
                      "easy",
                      "medium",
                      "hard"
                    ],
                    "default": "easy"
                  },
                  "tags": {
                    "type": "array",
                    "items": {
                      "type": "string"
                    },
                    "example": [
                      "networking",
                      "rest"
                    ]
                  }
                }
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "MCQ question created"
          }
        },
        "operationId": "MCQ_createQuestion"
      }
    },
